import { test } from "node:test";
import assert from "node:assert/strict";
import { setImmediate as tick } from "node:timers/promises";
import { InsufficientFundsError, WalletService, type WalletStore } from "../src/wallet/wallets.ts";
import { payoutAll } from "../src/wallet/payouts.ts";
import { refundOrder, type Order } from "../src/wallet/refunds.ts";

// In-memory store that yields on every call, like a real database round trip.
function memoryStore(balances: Record<string, number>): WalletStore & { balances: Record<string, number> } {
    return {
        balances,
        async load(id) {
            await tick();
            return id in balances ? balances[id] : null;
        },
        async save(id, cents) {
            await tick();
            balances[id] = cents;
        },
    };
}

function memoryOrders(orders: Order[]) {
    const rows = new Map(orders.map((o) => [o.id, o]));
    return { rows, get: async (id: string) => rows.get(id) ?? null, save: async (o: Order) => void rows.set(o.id, o) };
}

// Fail instead of hanging forever if transfers wait on each other.
async function within<T>(ms: number, work: Promise<T>): Promise<T> {
    let timer: NodeJS.Timeout | undefined;
    const timeout = new Promise<never>((_, reject) => {
        timer = setTimeout(() => reject(new Error(`still waiting after ${ms}ms (deadlock?)`)), ms);
    });
    try {
        return await Promise.race([work, timeout]);
    } finally {
        clearTimeout(timer);
    }
}

const total = (b: Record<string, number>) => Object.values(b).reduce((s, x) => s + x, 0);

test("a transfer moves money between wallets", async () => {
    const store = memoryStore({ alice: 1000, bob: 0 });
    await new WalletService(store).transfer("alice", "bob", 300);
    assert.deepEqual(store.balances, { alice: 700, bob: 300 });
});

test("insufficient funds changes nothing and releases the locks", async () => {
    const store = memoryStore({ alice: 100, bob: 0 });
    const wallets = new WalletService(store);
    await assert.rejects(wallets.transfer("alice", "bob", 500), InsufficientFundsError);
    await within(500, wallets.transfer("alice", "bob", 100));
    assert.deepEqual(store.balances, { alice: 0, bob: 100 });
});

test("two friends paying each other back at the same moment both complete", async () => {
    const store = memoryStore({ alice: 1000, bob: 1000 });
    const wallets = new WalletService(store);
    await within(1000, Promise.all([wallets.transfer("alice", "bob", 250), wallets.transfer("bob", "alice", 100)]));
    console.log("balances after concurrent transfers:", store.balances);
    assert.deepEqual(store.balances, { alice: 850, bob: 1150 });
});

test("a burst of concurrent transfers in every direction keeps the total", async () => {
    const ids = ["a", "b", "c", "d"];
    const store = memoryStore({ a: 500, b: 500, c: 500, d: 500 });
    const wallets = new WalletService(store);
    const jobs = [];
    for (let i = 0; i < 40; i++) {
        const from = ids[i % 4];
        const to = ids[(i * 3 + 1) % 4];
        if (from !== to) jobs.push(wallets.transfer(from, to, 10).catch(() => undefined));
    }
    await within(2000, Promise.all(jobs));
    assert.equal(total(store.balances), 2000);
});

test("payouts report which sellers were paid and which failed", async () => {
    const store = memoryStore({ market: 1000, s1: 0, s2: 0, s3: 0 });
    const report = await within(1000, payoutAll(new WalletService(store), "market", [
        { toId: "s1", amountCents: 400 },
        { toId: "s2", amountCents: 500 },
        { toId: "s3", amountCents: 300 },
        { toId: "ghost", amountCents: 1 },
    ], 2));
    assert.deepEqual(report.paid.sort(), ["s1", "s2"]);
    assert.deepEqual(report.failed.map((f) => [f.toId, f.reason]).sort(), [["ghost", "error"], ["s3", "insufficient_funds"]]);
    assert.equal(total(store.balances), 1000);
});

test("a refund can't exceed what is left on the order", async () => {
    const store = memoryStore({ buyer: 0, seller: 5000 });
    const orders = memoryOrders([{ id: "o1", buyerId: "buyer", sellerId: "seller", amountCents: 3000, refundedCents: 0 }]);
    const wallets = new WalletService(store);
    await refundOrder(orders, wallets, "o1", 2000);
    await assert.rejects(refundOrder(orders, wallets, "o1", 1500), /Only 1000 cents/);
    assert.deepEqual(store.balances, { buyer: 2000, seller: 3000 });
    assert.equal(orders.rows.get("o1")?.refundedCents, 2000);
});

test("a refund and a new purchase between the same two wallets don't block each other", async () => {
    const store = memoryStore({ buyer: 1000, seller: 1000 });
    const orders = memoryOrders([{ id: "o1", buyerId: "buyer", sellerId: "seller", amountCents: 600, refundedCents: 0 }]);
    const wallets = new WalletService(store);
    await within(1000, Promise.all([refundOrder(orders, wallets, "o1", 600), wallets.transfer("buyer", "seller", 250)]));
    assert.deepEqual(store.balances, { buyer: 1350, seller: 650 });
});
